127	// snapshotConnectionsLocked copies only the serialized connection state and
128	// deep-copies chunks. The caller must hold the fetcher's connMu.
129	func snapshotConnectionsLocked(connections []*connection) []*connection {
130		snapshot := make([]*connection, len(connections))
131		for i, conn := range connections {
132			if conn == nil {
133				continue
134			}
135			copyConn := &connection{
136				ID:         conn.ID,
137				Role:       conn.Role,
138				State:      conn.State,
139				Downloaded: conn.Downloaded,
140				Completed:  conn.Completed,
141			}
142			if conn.Chunk != nil {
143				copyChunk := *conn.Chunk
144				if conn.Chunk.End != nil {
145					end := *conn.Chunk.End
146					copyChunk.End = &end
147				}
148				copyConn.Chunk = &copyChunk
149			}
150			snapshot[i] = copyConn
151		}
152		return snapshot
153	}
