171			fetcher.rangeReprobeEligible = fd.RangeReprobeEligible
172			fetcher.rangeValidatorPinned = fd.RangeValidatorPinned
173			fetcher.sequentialSizeUnknown = fd.SequentialSizeUnknown
174			if fd.SizeKnown != nil {
175				known := *fd.SizeKnown
176				fetcher.sizeKnown = &known
177			}
178			if fd.Range != nil && fetcher.meta.Res != nil {
179				// Recovery-critical resource fields live in the same persisted snapshot
180				// as Connections, making them authoritative over task metadata that may
181				// have been saved just before or after this record.
